<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #121a2f;
      --panel-border: #24314f;
      --text: #e5eefc;
      --muted: #9fb0d0;
      --accent: #6ea8ff;
      --accent-strong: #8bb7ff;
      --error: #ff7a8a;
      --field: #0f1730;
      --field-border: #2a3760;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(110, 168, 255, 0.18), transparent 35%),
        linear-gradient(180deg, #0a0f1c 0%, var(--bg) 100%);
      color: var(--text);
      display: grid;
      place-items: center;
      padding: 24px;
    }

    .support-card {
      width: min(100%, 560px);
      background: rgba(18, 26, 47, 0.94);
      border: 1px solid rgba(36, 49, 79, 0.9);
      border-radius: 20px;
      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.35);
      padding: 32px;
      backdrop-filter: blur(10px);
    }

    h1 {
      margin: 0 0 8px;
      font-size: clamp(1.7rem, 4vw, 2.2rem);
      letter-spacing: -0.03em;
    }

    .subtitle {
      margin: 0 0 24px;
      color: var(--muted);
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 600;
      color: var(--text);
    }

    input {
      width: 100%;
      border: 1px solid var(--field-border);
      background: var(--field);
      color: var(--text);
      border-radius: 12px;
      padding: 14px 16px;
      font: inherit;
      outline: none;
      transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
    }

    input::placeholder {
      color: #7f8eb2;
    }

    input:focus {
      border-color: var(--accent);
      box-shadow: 0 0 0 4px rgba(110, 168, 255, 0.16);
    }

    .helper-text {
      margin: 0;
      color: var(--muted);
      font-size: 0.92rem;
      line-height: 1.5;
    }

    .error-text {
      margin: 0;
      color: var(--error);
      font-size: 0.92rem;
      line-height: 1.5;
      min-height: 1.4em;
    }

    .error-text[hidden] {
      display: none;
    }

    button {
      border: 0;
      border-radius: 12px;
      padding: 14px 18px;
      font: inherit;
      font-weight: 700;
      color: #07101f;
      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
      cursor: pointer;
      box-shadow: 0 14px 30px rgba(110, 168, 255, 0.22);
      transition: transform 0.2s ease, box-shadow 0.2s ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 16px 34px rgba(110, 168, 255, 0.28);
    }

    button:focus-visible {
      outline: 3px solid rgba(139, 183, 255, 0.7);
      outline-offset: 3px;
    }

    .status {
      margin: 0;
      min-height: 1.4em;
      color: var(--muted);
    }
  </style>
</head>
<body>
  <main class="support-card">
    <h1>Contact support</h1>
    <p class="subtitle">Send us your details and we’ll get back to you as soon as possible.</p>

    <form id="support-form" novalidate>
      <div class="form-field">
        <label for="full-name">Full name</label>
        <input id="full-name" name="fullName" type="text" autocomplete="name" required>
        <p class="error-text" id="full-name-error" hidden></p>
      </div>

      <div class="form-field">
        <label for="email-address">Email address</label>
        <input id="email-address" name="email" type="email" autocomplete="email" required>
        <p class="error-text" id="email-error" hidden></p>
      </div>

      <div class="form-field">
        <label for="phone-number">Phone number</label>
        <input
          id="phone-number"
          name="phone"
          type="tel"
          autocomplete="tel"
          aria-describedby="phone-helper"
          placeholder="+1 555 123 4567"
        >
        <p class="helper-text" id="phone-helper">Optional. Use a format like +1 555 123 4567 or 555-123-4567.</p>
      </div>

      <button type="submit">Submit request</button>
      <p class="status" id="form-status" aria-live="polite"></p>
    </form>
  </main>

  <script>
    const form = document.getElementById("support-form");
    const status = document.getElementById("form-status");
    const fields = {
      fullName: {
        input: document.getElementById("full-name"),
        error: document.getElementById("full-name-error"),
        message: "Please enter your full name."
      },
      email: {
        input: document.getElementById("email-address"),
        error: document.getElementById("email-error"),
        message: "Please enter a valid email address."
      }
    };

    const showError = ({ input, error, message }) => {
      error.textContent = message;
      error.hidden = false;
      input.setAttribute("aria-invalid", "true");
      input.setAttribute("aria-describedby", `${input.id}-error${input.id === "phone-number" ? " phone-helper" : ""}`.trim());
    };

    const clearError = ({ input, error }) => {
      error.textContent = "";
      error.hidden = true;
      input.removeAttribute("aria-invalid");
    };

    const validateField = (field, value) => {
      if (!value.trim()) {
        return field.message;
      }

      if (field.input.type === "email" && !field.input.validity.valid) {
        return field.message;
      }

      return "";
    };

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      let firstInvalid = null;

      Object.values(fields).forEach((field) => {
        const message = validateField(field, field.input.value);

        if (message) {
          showError(field);
          field.error.textContent = message;
          field.error.hidden = false;
          if (!firstInvalid) {
            firstInvalid = field.input;
          }
        } else {
          clearError(field);
        }
      });

      if (firstInvalid) {
        status.textContent = "Please fix the highlighted fields.";
        firstInvalid.focus();
        return;
      }

      status.textContent = "Your message has been prepared for submission.";
      form.reset();
    });

    Object.values(fields).forEach(({ input, error }) => {
      input.addEventListener("input", () => {
        if (!error.hidden) {
          const message = validateField({ input, message: error.textContent }, input.value);
          if (message) {
            error.textContent = message;
            error.hidden = false;
          } else {
            clearError({ input, error });
            if (status.textContent === "Please fix the highlighted fields.") {
              status.textContent = "";
            }
          }
        }
      });
    });
  </script>
</body>
</html>
